suppressMessages(library(dplyr))
ph <- readRDS("calibration/alum/ph_obs.rds") |> filter(value > 4, value < 11)
fp <- function(p, o, s) exp(-(p - o)^2 / (2 * s^2))
ph$fpH <- fp(ph$value, 7, 1); ph$zone <- ifelse(ph$depth >= 17, "bottom >=17 m (k_s)", ifelse(ph$depth <= 10, "upper <=10 m (k_w)", "10-17 m"))
ph$season <- ifelse(ph$mo %in% c(12, 1, 2, 3), "summer Dec-Mar", ifelse(ph$mo %in% 6:8, "winter Jun-Aug", "other"))
cat("mean fpH (pH_opt 7, sigma 1) by zone and season:\n"); print(ph |> group_by(zone, season) |> summarise(n = n(), pH = round(median(value), 2), fpH = round(mean(fpH), 2), .groups = "drop"))
cat("\nby year, upper (<=10 m) and bottom:\n"); print(ph |> group_by(yr, zone) |> summarise(pH = round(median(value), 2), fpH = round(mean(fpH), 2), .groups = "drop") |> tidyr::pivot_wider(names_from = zone, values_from = c(pH, fpH)))
cat("\nanoxia link: bottom pH when bottom DO < 2 vs >= 2 (new buoy)\n")
ox <- targets::tar_read_raw("aeme_buoy_data") |> filter(var_aeme == "CHM_oxy", depth >= 17) |> transmute(Date, depth, oxy = value)
j <- inner_join(ph |> filter(depth >= 17), ox, by = c("Date", "depth")); print(j |> group_by(anoxic = oxy < 2) |> summarise(n = n(), pH = round(median(value), 2), fpH = round(mean(fpH), 2)))
